function checkPin(d = digits) {
  if (d.join('') === PIN) {
    setUnlocked(true)
  } else {
    setPinError(true)
    setDigits(['', '', '', ''])
    setTimeout(() => {
      const el = document.getElementById('pin-0')
      if (el) (el as HTMLInputElement).focus()
    }, 100)
  }
}
